"use client";
import { useState } from "react";
import {
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { ChartLegend } from "./chart-legend";
import { formatNumber } from "./chart-card";
import { SCATTER_DEMO_RANGES } from "./chart-demo-data";
import {
  average,
  type ChartCommonProps,
  ChartFrame,
  type ChartRange,
  chartAxis,
  ink,
  PeriodSelect,
  StatTiles,
  shortNumber,
  useChartRange,
} from "./pro-chart";
export interface ScatterPoint {
  x: number;
  y: number;
  z?: number;
  label?: string;
}
export interface ScatterSeries {
  label: string;
  points: ScatterPoint[];
  color?: string;
}
export interface ScatterChartRange extends ChartRange {
  yDomain?: [number, number];
  series: ScatterSeries[];
}
export interface ScatterChartCardProps extends ChartCommonProps {
  series?: ScatterSeries[];
  ranges?: ScatterChartRange[];
  axisLabels?: [string, string];
  formatX?: (value: number) => string;
  bubble?: boolean;
  tiles?: boolean;
  legend?: "tiles" | "inline";
  plotFlexible?: boolean;
  xDomain?: [number, number];
  yDomain?: [number, number];
  zDomain?: [number, number | "dataMax"];
}
export const SCATTER_SERIES: ScatterSeries[] = SCATTER_DEMO_RANGES[0]!.series;
const RANGES: ScatterChartRange[] = SCATTER_DEMO_RANGES;

export function ScatterChartCard({
  series,
  ranges: supplied,
  title = "Revenue per account",
  axisLabels = ["Sessions", "Revenue"],
  formatX = shortNumber,
  bubble,
  tiles = true,
  legend = "tiles",
  plotFlexible = false,
  xDomain,
  yDomain,
  zDomain,
  ...props
}: ScatterChartCardProps = {}) {
  const ranges = supplied ?? (series ? undefined : RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    groups = period.current?.series ?? series ?? SCATTER_SERIES,
    [active, setActive] = useState<{ series: number; point?: number } | null>(null),
    reduced = useHydratedReducedMotion(),
    format = props.format ?? formatNumber,
    activeInk = (i: number) => groups[i]?.color ?? ink(i).replace(")", "-active)"),
    bubbles = bubble ?? groups.some((s) => s.points.some((p) => p.z != null)),
    point = active?.point != null ? groups[active.series]?.points[active.point] : undefined,
    value =
      point?.y ??
      (active
        ? average(groups[active.series]?.points.map((p) => p.y) ?? [])
        : (period.current?.headline ??
          props.headline ??
          average(groups.flatMap((s) => s.points.map((p) => p.y)))));
  return (
    <ChartFrame
      title={
        point
          ? `${point.label ?? groups[active!.series]?.label} · ${formatX(point.x)}`
          : active
            ? (groups[active.series]?.label ?? title)
            : title
      }
      value={value}
      format={format}
      delta={active == null ? (period.current?.delta ?? props.delta) : undefined}
      animateNumber
      pulseKey={active ? `${active.series}-${active.point}` : null}
      className={props.className}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            setActive(null);
            period.select(id);
          }}
          label={period.current?.label ?? props.range ?? "This quarter"}
        />
      }
      footer={
        tiles &&
        legend === "tiles" && (
          <StatTiles
            items={groups.map((s, i) => ({
              label: `${s.label}${bubbles ? " · avg" : ""}`,
              value: format(average(s.points.map((p) => p.y))),
              color: s.color ?? ink(i),
              activeColor: activeInk(i),
            }))}
            responsive
            fillLastOdd
            inactiveOpacity={0.4}
            focusable={false}
            active={active?.series}
            onHover={(i) => setActive(i == null ? null : { series: i, point: 0 })}
          />
        )
      }
    >
      <div className={plotFlexible ? "min-h-0 w-full flex-1" : "h-[196px] w-full"}>
        <ResponsiveContainer width="100%" height="100%">
          <ScatterChart margin={{ top: 8, right: 8, bottom: 0, left: 0 }}>
            <CartesianGrid stroke="var(--color-chart-track)" strokeDasharray="4 4" />
            <XAxis
              {...chartAxis}
              type="number"
              domain={xDomain}
              dataKey="x"
              tickCount={5}
              tickFormatter={formatX}
              tickMargin={10}
            />
            <YAxis
              {...chartAxis}
              type="number"
              domain={period.current?.yDomain ?? yDomain}
              dataKey="y"
              width={48}
              tickCount={4}
              tickFormatter={(n: number) =>
                Math.abs(n) >= 1000 ? `${Math.round(n / 100) / 10}K` : `${n}`
              }
            />
            <ZAxis
              type="number"
              domain={zDomain}
              dataKey={bubbles ? "z" : undefined}
              range={bubbles ? [90, 620] : [80, 80]}
            />
            <Tooltip content={() => null} cursor={false} />
            {groups.map((s, i) => (
              <Scatter
                key={s.label}
                name={s.label}
                data={s.points}
                fill={s.color ?? ink(i)}
                stroke={activeInk(i)}
                fillOpacity={active && active.series !== i ? 0.25 : 0.85}
                strokeOpacity={active && active.series !== i ? 0.25 : 1}
                strokeWidth={1.5}
                isAnimationActive={!reduced}
                animationDuration={450}
                animationEasing="linear"
                onMouseEnter={(_, p) => setActive({ series: i, point: p })}
                onMouseLeave={() => setActive(null)}
              >
                {s.points.map((p, j) => (
                  <Cell
                    key={p.label ?? j}
                    className="cursor-default transition-opacity duration-200 ease-out"
                  />
                ))}
              </Scatter>
            ))}
          </ScatterChart>
        </ResponsiveContainer>
      </div>
      <div className="flex justify-between text-caption-1-medium text-text-tertiary">
        <span>{axisLabels[1]}</span>
        <span>{axisLabels[0]}</span>
      </div>
      {legend === "inline" && (
        <ChartLegend
          items={groups.map((s, i) => ({
            label: s.label,
            value: format(average(s.points.map((p) => p.y))),
            color: s.color ?? ink(i),
          }))}
        />
      )}
    </ChartFrame>
  );
}
